mapper.sql:
FROM journal_entry je

    INNER JOIN journal_entry_tag jet
        ON jet.journal_entry_id = je.id
        AND jet.tag_id = #{query.tagId}



        AND (
            je.title LIKE CONCAT('%', #{query.keyword}, '%')
            OR je.content_md LIKE CONCAT('%', #{query.keyword}, '%')
            OR EXISTS (
                SELECT 1
                FROM journal_entry_tag keyword_jet
                INNER JOIN tag keyword_tag ON keyword_tag.id = keyword_jet.tag_id
                WHERE keyword_jet.journal_entry_id = je.id
                  AND keyword_tag.name LIKE CONCAT('%', #{query.keyword}, '%')
            )
        )


        AND je.entry_type = #{query.entryType}


        AND je.entry_date >= #{query.startDate}


        AND je.entry_date <= #{query.endDate}
